using Godot;
using MySimulator.Rebuild;
using System;
using System.Collections.Generic;
using System.Text.Json;
namespace MySim {
// Compound convex resources are baked on CI from intact visible source body parts.
// They are encrypted with the build; no hull vertex data is written to public Git or diagnostics.
public static class NativeCarColliders {
 const string Root="res://assets/generated_native_car_hulls/";
 static bool WheelTemplate(string name)=>System.Text.RegularExpressions.Regex.IsMatch(name,@"^LOD_A_(TYRE|TIRE|WHEEL|CALIPER|BRAKE_DISC|DISC|ROTOR|HUB)(_|$)",System.Text.RegularExpressions.RegexOptions.IgnoreCase);
 static bool Volume(List<Vector3> points){if(points.Count<4)return false;var origin=points[0];Vector3 axis=Vector3.Zero,cross=Vector3.Zero;foreach(var p in points)if((p-origin).LengthSquared()>axis.LengthSquared())axis=p-origin;if(axis.LengthSquared()<.000001f)return false;foreach(var p in points){var n=axis.Cross(p-origin);if(n.LengthSquared()>cross.LengthSquared())cross=n;}if(cross.LengthSquared()<.00000001f)return false;cross=cross.Normalized();foreach(var p in points)if(Mathf.Abs(cross.Dot(p-origin))>.001f)return true;return false;}
 public static async void Bake(Node owner,string selection){try{
  System.IO.Directory.CreateDirectory(ProjectSettings.GlobalizePath(Root));var report=new List<object>();foreach(var value in selection.Split(',')){int car=int.Parse(value);if(car<0||car>=CarCatalog.Count)throw new ArgumentOutOfRangeException("car");var model=CarLoader.Load(CarCatalog.Folders[car]);owner.AddChild(model);var inverse=model.GlobalTransform.AffineInverse();var groups=new SortedDictionary<string,List<Vector3>>();var nodes=model.FindChildren("*","MeshInstance3D",true,false);
   foreach(var node in nodes){var mesh=(MeshInstance3D)node;string name=mesh.Name.ToString();if(!mesh.IsVisibleInTree()||mesh.Mesh==null||WheelTemplate(name)||name.StartsWith("LOD_A_INT_",StringComparison.OrdinalIgnoreCase))continue;int role=name.IndexOf("_mm_",StringComparison.OrdinalIgnoreCase);string part=role<0?name:name.Substring(0,role);if(!groups.ContainsKey(part))groups[part]=new();var transform=inverse*mesh.GlobalTransform;foreach(var point in mesh.Mesh.GetFaces())groups[part].Add(transform*point-Vector3.Up*.65f);
   }nodes.Clear();var files=new List<string>();var skipped=new List<string>();Aabb coverage=new();bool first=true;int index=0;
   foreach(var group in groups){if(!Volume(group.Value)){skipped.Add(group.Key);continue;}var arrays=new Godot.Collections.Array();arrays.Resize((int)Mesh.ArrayType.Max);arrays[(int)Mesh.ArrayType.Vertex]=group.Value.ToArray();var mesh=new ArrayMesh();mesh.AddSurfaceFromArrays(Mesh.PrimitiveType.Triangles,arrays);arrays.Dispose();var shape=mesh.CreateConvexShape(true,true);if(shape==null||shape.Points.Length<4)throw new Exception("Failed source convex body part: "+group.Key);string path=Root+"car-"+car.ToString("00")+"-part-"+(index++).ToString("000")+".res";if(ResourceSaver.Save(shape,path)!=Error.Ok)throw new Exception("Could not save native hull");files.Add(path);foreach(var point in shape.Points){if(!point.IsFinite())throw new Exception("Nonfinite native hull");if(first){coverage=new Aabb(point,Vector3.Zero);first=false;}else coverage=coverage.Expand(point);}
   }
   if(files.Count==0||coverage.Size.Z<RecoveredGeometry.Wheelbase[car])throw new Exception("Source body hull coverage is incomplete");var wheels=CarLoader.AttachWheels(model,car);var wheelCentres=Array.ConvertAll(wheels,w=>new[]{w.Position.X,w.Position.Y-.65f,w.Position.Z});var wheelRadii=Array.ConvertAll(wheels,w=>w.GetMeta("radius").AsSingle());var manifest=new {car,files,wheelCentres,wheelRadii,parts=files.Count,skippedPlanarParts=skipped,centre=new[]{coverage.GetCenter().X,coverage.GetCenter().Y,coverage.GetCenter().Z},size=new[]{coverage.Size.X,coverage.Size.Y,coverage.Size.Z},scope="Visible source body-part compound convex approximation; wheel rotational bodies and full collision/visual acceptance remain separate"};System.IO.File.WriteAllText(ProjectSettings.GlobalizePath(Root+"car-"+car.ToString("00")+".json"),JsonSerializer.Serialize(manifest));report.Add(manifest);model.QueueFree();await owner.ToSignal(owner.GetTree(),SceneTree.SignalName.ProcessFrame);GD.Print("BAKED_NATIVE_BODY car=",car," convexParts=",files.Count);
  }
  System.IO.Directory.CreateDirectory("outputs/cloud-game");System.IO.File.WriteAllText("outputs/cloud-game/native-hull-summary.json",JsonSerializer.Serialize(report,new JsonSerializerOptions {WriteIndented=true}));CleanExit.Request(owner);
 }catch(Exception e){GD.PushError(e.ToString());CleanExit.Request(owner,1);}}
 public static void ConfigureWheels(NativeSuspensionVehicle body,int car){if(body.RecoveredWheelCentres!=null)return;string path=Root+"car-"+car.ToString("00")+".json";if(!Godot.FileAccess.FileExists(path))return;using var manifest=JsonDocument.Parse(Godot.FileAccess.GetFileAsString(path));if(!manifest.RootElement.TryGetProperty("wheelCentres",out var centres))return;var radii=manifest.RootElement.GetProperty("wheelRadii");body.RecoveredWheelCentres=new Vector3[4];body.RecoveredWheelRadii=new float[4];for(int i=0;i<4;i++){var p=centres[i];body.RecoveredWheelCentres[i]=new Vector3(p[0].GetSingle(),p[1].GetSingle(),p[2].GetSingle());body.RecoveredWheelRadii[i]=radii[i].GetSingle();}}
 public static bool Install(RigidBody3D body,int car){string path=Root+"car-"+car.ToString("00")+".json";if(!Godot.FileAccess.FileExists(path)){if(System.Environment.GetEnvironmentVariable("MYSIM_REQUIRE_NATIVE_CAR_HULLS")=="1")throw new Exception("Required native source-body hull cache missing for car "+car);return false;}using var manifest=JsonDocument.Parse(Godot.FileAccess.GetFileAsString(path));int count=0;foreach(var entry in manifest.RootElement.GetProperty("files").EnumerateArray()){string file=entry.GetString();if(!file.StartsWith(Root,StringComparison.Ordinal)||file.Contains(".."))throw new Exception("Invalid hull resource path");var shape=GD.Load<ConvexPolygonShape3D>(file);if(shape==null)throw new Exception("Native hull resource missing");body.AddChild(new CollisionShape3D {Shape=shape,Name="SourceBodyHull"+count++});}if(count==0)throw new Exception("Empty native source hull set");GD.Print("NATIVE_SOURCE_BODY_COLLIDERS car=",car," parts=",count);return true;}
}
}
